contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint256 seed, uint256 amount) public {
        require(seed > 0 && amount > 0);
        require(address(this).balance >= amount);

        uint256 before = address(this).balance;

        // give c some extra balance via its fallback
        address(c).call{value: seed}("");
        require(address(c).balance >= seed);

        // drive go with only msg.value = amount
        c.go{value: amount}();

        // P: target receives only amount, owner (this contract, as deployer) receives the rest => total conserved
        assert(address(this).balance == before);
    }

    receive() external payable {}
    fallback() external payable {}
}

