contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint256 amount) external {
        // leave a strictly positive leftover for C beyond the forwarded value
        require(address(this).balance > amount);
        uint256 extra = address(this).balance - amount;

        // fund C via its payable fallback so it holds extra ether
        (bool ok, ) = address(c).call{value: extra}("");
        require(ok);
        uint256 cBalBefore = address(c).balance;
        require(cBalBefore > amount);

        uint256 ownerBefore = c.owner().balance;

        c.go{value: amount}();

        // P: entire remaining balance goes to the owner, so the owner gains
        // at least (cBalBefore - amount) (plus anything refunded by target).
        // M: the leftover is sent to the target instead, so the owner gains 0.
        assert(c.owner().balance - ownerBefore >= cBalBefore - amount);
    }

    receive() external payable {}
    fallback() external payable {}
}
